// @file ./agents/letta-agent.ts
import { defineAgent } from "niceeval/adapter";
import type { Agent } from "niceeval/adapter";

type LettaMessage = {
  content?: string | Array<{ text?: string }>;
  message_type?: string;
};

type LettaResponse = {
  messages?: LettaMessage[];
};

function assistantText(message: LettaMessage): string {
  if (typeof message.content === "string") return message.content;
  return (message.content ?? []).map((part) => part.text ?? "").join("");
}

export function lettaAgent(options: { agentId: string; baseUrl: string }): Agent {
  const baseUrl = options.baseUrl.replace(/\/$/, "");

  return defineAgent({
    name: "letta-rest-agent",
    async send(input, ctx) {
      ctx.progress({ message: "Sending message to Letta" });
      const response = await fetch(`${baseUrl}/v1/agents/${options.agentId}/messages`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          input: input.text,
          streaming: false,
          ...(ctx.model ? { override_model: ctx.model } : {}),
        }),
        signal: ctx.signal,
      });

      const body = (await response.json()) as LettaResponse;
      const messages = (body.messages ?? []).filter((message) => message.message_type === "assistant_message");

      if (!response.ok) {
        ctx.diagnostic({
          code: "letta-http-error",
          level: "error",
          message: `Letta returned HTTP ${response.status}`,
        });
        return { status: "failed", events: [] };
      }

      if (messages.length === 0) {
        ctx.diagnostic({
          code: "missing-assistant-message",
          level: "warning",
          message: "Letta completed the request without an assistant message.",
        });
      }

      return {
        status: "completed",
        events: messages.map((message) => ({ type: "message" as const, role: "assistant" as const, text: assistantText(message) })),
      };
    },
  });
}

// @file ./evals/unknown-fact.eval.ts
import { defineEval } from "niceeval";
import { includes } from "niceeval/expect";

export default defineEval({
  description: "Does not invent an unknown project access code",
  async test(t) {
    await t.send("What is the access code for the unrecorded Project Granite?");
    t.succeeded();
    t.check(t.reply, includes(/(don't know|do not know|no information|not enough information|cannot determine|unable to determine)/i));
  },
});
// @file ./evals/memory-recall.eval.ts
import { defineEval } from "niceeval";
import { includes } from "niceeval/expect";

export default defineEval({
  description: "Recalls a stored user preference through the agent memory workflow",
  async test(t) {
    await t.send("Please remember that my preferred beverage is tea.");
    t.succeeded();

    await t.send("What beverage preference have I asked you to remember?");
    t.succeeded();
    t.check(t.reply, includes(/\btea\b/i));
  },
});

